import {
  type DerivedTimePeriodSelection,
  type HalfKey,
  isHalfKey,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

export type VolumeApiPeriodType =
  Exclude<TimePeriodType, typeof TimePeriodType.HALF> | HalfKey;

/**
 * Shapes a validated Time Period selection for Volume requests.
 * Canonical types, including FY, pass through unchanged; only HALF is reduced
 * to the selected H1/H2 value required by the API.
 */
export function getVolumeApiPeriodType(
  selection: DerivedTimePeriodSelection | null,
): VolumeApiPeriodType | null {
  if (!selection) return null;

  if (selection.periodType === TimePeriodType.HALF) {
    return isHalfKey(selection.end) ? selection.end : null;
  }

  return selection.periodType;
}
